import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        email TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria.
    Supports: username, email, role filters.
    """
    username = request.args.get('username', '')
    role = request.args.get('role', '')
    email = request.args.get('email', '')

    # Build dynamic query based on provided filters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if role:
        conditions.append(f"role = '{role}'")
    if email:
        conditions.append(f"email LIKE '%{email}%'")

    if not conditions:
        return jsonify({'error': 'At least one search parameter required'}), 400

    where_clause = ' AND '.join(conditions)
    query = f"SELECT id, username, role, email FROM users WHERE {where_clause}"

    # Log the search for compliance
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
               ('user_search', f'query_filters: username={username}, role={role}, email={email}'))
    db.commit()

    try:
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, role, email FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    db = get_db()
    try:
        db.execute('INSERT INTO users (username, password_hash, email) VALUES (?, ?, ?)',
                   (data['username'], password_hash, data.get('email', '')))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/admin/dump', methods=['GET'])
def admin_dump():
    """Debug endpoint - should be disabled in production"""
    auth = request.headers.get('X-Admin-Token')
    if auth != os.environ.get('ADMIN_TOKEN', 'changeme'):
        return jsonify({'error': 'Unauthorized'}), 403
    db = get_db()
    users = db.execute('SELECT * FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
